import frappe
from frappe import _
from frappe.model.document import Document
from frappe.utils import now_datetime


class TipodeComissao(Document):
	def validate(self):
		self.nome_tipo = (self.nome_tipo or "").strip()
		if not self.nome_tipo:
			frappe.throw(_("Informe o nome do tipo de comissão."))
		self.validate_duplicate()
		self.record_bylaws_change()

	def validate_duplicate(self):
		# The name is generated by ID, so uniqueness is enforced per company.
		existing = frappe.db.exists(
			"Tipo de Comissao",
			{"nome_tipo": self.nome_tipo, "empresa": self.empresa, "name": ("!=", self.name)},
		)
		if existing:
			frappe.throw(
				_("Já existe um tipo de comissão com o nome {0} para a empresa {1}.").format(
					frappe.bold(self.nome_tipo), frappe.bold(self.empresa)
				)
			)

	def record_bylaws_change(self):
		"""Record the previous text in the history whenever the bylaws change."""
		reason = (self.motivo_alteracao_regimento or "").strip()
		self.motivo_alteracao_regimento = None

		before = self.get_doc_before_save()
		previous_text = (before.regimento if before else None) or ""
		current_text = self.regimento or ""
		if previous_text == current_text:
			return

		if previous_text and not reason:
			frappe.throw(_("Informe o motivo da alteração do regimento."))

		self.append(
			"historico_regimento",
			{
				"versao": len(self.historico_regimento) + 1,
				"data_alteracao": now_datetime(),
				"responsavel": frappe.session.user,
				"motivo": reason or _("Versão inicial do regimento"),
				"texto_anterior": previous_text,
			},
		)
